def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_prev = 0.0
    desperate_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            bid = None
            if prev:
                bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > strong_prev:
                    strong_prev = float(bid)
            if opp.get('budget', 0) > 500:
                if bid is not None and float(bid) >= 80:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive:
        return min(float(budget), 28.0)

    low_supply = supply <= 17
    high_supply = supply >= 22
    critical_me = hp <= 2 or no_water_days >= 1
    stable_me = hp >= 6 and no_water_days == 0

    if not prev_bids:
        if critical_me:
            return min(float(budget), 84.0)
        if high_supply:
            return min(float(budget), 42.0)
        return min(float(budget), 30.0)

    top_prev = max(prev_bids)
    avg_prev = sum(prev_bids) / float(len(prev_bids))

    if critical_me:
        target = max(0.9 * DAILY_SALARY, top_prev + 2.0)
        if high_supply:
            target += 6.0
        return min(float(budget), float(target))

    if low_supply:
        if stable_me and top_prev >= 80:
            return min(float(budget), 12.0)
        if desperate_count >= 2:
            return min(float(budget), 18.0)
        return min(float(budget), max(20.0, avg_prev * 0.45))

    if high_supply:
        if top_prev < 75:
            return min(float(budget), max(46.0, top_prev + 2.0))
        if rich_aggressive >= 2 and stable_me:
            return min(float(budget), 35.0)
        return min(float(budget), max(52.0, top_prev + 1.5))

    if top_prev >= 110:
        if stable_me:
            return min(float(budget), 22.0)
        return min(float(budget), 68.0)

    if top_prev >= 85:
        if stable_me:
            return min(float(budget), 26.0)
        return min(float(budget), 60.0)

    target = max(38.0, top_prev + 1.5)
    if day >= 8 and hp >= 5:
        target *= 0.9
    return min(float(budget), float(target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no one alive, take what you need
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for oid, o in alive_opps:
        pt = o.get('previous_trace', None)
        if isinstance(pt, dict):
            b = pt.get('bid', None)
            if b is not None:
                prev_bids.append(float(b))
        elif isinstance(pt, list) and len(pt) > 0:
            # Shouldn't happen per spec, but be defensive
            last = pt[-1]
            b = last.get('bid', None)
            if b is not None:
                prev_bids.append(float(b))

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Determine how many full allocations are feasible; use int indices safely
    # supply is 15..25 so thresholding is stable
    supply_level = 0
    if supply >= 21:
        supply_level = 2
    elif supply >= 18:
        supply_level = 1
    else:
        supply_level = 0

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Core strategy:
    # - If others were bidding high yesterday, we match a fraction above a baseline to avoid losing.
    # - If my hp is low, bid more conservatively to preserve budget for later survival.
    # - If supply is higher, we can bid slightly less since water is effectively more available.

    # Baseline bids by supply level
    if supply_level == 2:
        base = DAILY_SALARY * 0.45
    elif supply_level == 1:
        base = DAILY_SALARY * 0.55
    else:
        base = DAILY_SALARY * 0.65

    # Pressure adjustment based on yesterday's highest bid
    # If someone bid near/above 0.85*salary, assume they were fighting for survival.
    pressure = 0.0
    if highest_prev_bid > 0:
        pressure = highest_prev_bid / DAILY_SALARY

    if pressure >= 0.85:
        # Match pressure but not fully; aim to beat mid-tier while conserving budget.
        if hp > 3:
            target = base + (highest_prev_bid - base) * 0.55
        else:
            target = base + (highest_prev_bid - base) * 0.35
    elif pressure >= 0.6:
        target = base + (highest_prev_bid - base) * 0.35
    else:
        # If yesterday was low, bid just enough to secure water.
        target = base * 0.95

    # Safety caps to avoid overspending
    # Keep within budget and avoid bidding above a reasonable fraction of budget.
    budget_cap = budget

    # If my hp is critically low, prioritize survival by bidding closer to salary.
    if hp <= 2:
        target = max(target, DAILY_SALARY * 0.75)
    elif hp <= 4:
        target = max(target, DAILY_SALARY * 0.6)

    # If budget is too low, scale down proportionally
    if budget < DAILY_SALARY * 0.2:
        target = min(target, budget)
    else:
        # Do not exceed ~1.1 salary to prevent waste
        target = min(target, DAILY_SALARY * 1.1)

    bid = min(budget_cap, target)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)
